INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(383600, 0, 3836, 0, 0, 8, 'Magtheridon''s Lair', 'Magtheridon''s Lair is the deepest vault beneath Hellfire Citadel, a great round chamber at the end of a corridor held by Hellfire warders. At its center the pit lord Magtheridon, once master of Outland, is held fast in bonds of shadow, and five Hellfire channelers stand about him, never pausing in the work that keeps him bound. Five Manticron cubes stand around the chamber''s edge, and tall columns hold up the vaulted roof above them. Magtheridon rages at his jailers without end, calling them vermin and leeches, asking how long they think their sorcery can hold him, and swearing that he will crush Illidan and reclaim Outland as his own. Whoever comes this far comes to end him, and to do that they must first strike down his jailers, and so set him free.', 'zones/magtheridons_lair.txt (map 544: area 3836 only); DB spawns map 544: Magtheridon 17257, five Hellfire Channelers 17256 around him, twelve Hellfire Warders 18829; gameobjects Manticron Cube 181713 (five), Magtheridon Column 184634-184639, Doodad_HF_Mag_door01 183847; smart_scripts 17256 (Shadow Grasp channeled on him out of combat); creature_text 17257 group 0 (Wretched, meddling insects! Release me...; Vermin! Leeches!; Illidan is an arrogant fool! I will crush him and reclaim Outland as my own!; How long do you believe your pathetic sorcery can hold me?); boss_magtheridon.cpp (he breaks free once the channelers are attacked); shadowmoon.json (Magtheridon ruled from the Black Temple until Illidan drove him out); warcraft.wiki.gg/wiki/Magtheridon (Lord of Outland; bound beneath Hellfire Citadel by Illidan)'),
(383601, 2, 3836, 1, 0, 8, 'Magtheridon', 'Magtheridon is a pit lord of the Burning Legion, and for a time he was the master of Outland, ruling from the Black Temple until Illidan Stormrage and his allies cast him down. Now he is a prisoner chained beneath Hellfire Citadel, held by channelers whose sorcery never rests. He has lost none of his pride. He scorns his jailers as parasites and leeches, tells them to take his blood and choke on it, offers whoever sets him free a merciful death, perhaps, and calls Illidan an arrogant fool whom he will crush before reclaiming Outland as his own.', 'creature_text 17257; boss_magtheridon.cpp; instance_magtheridons_lair.cpp; shadowmoon.json (Magtheridon ruled from the Black Temple until Illidan drove him out with the help of Akama''s Broken); warcraft.wiki.gg/wiki/Magtheridon (Warcraft III: The Frozen Throne: defeated by Illidan, Kael''thas, Vashj and Akama; bound beneath Hellfire Citadel); quests 11002/11003 descriptions (his head)'),
(383602, 3, 3836, 1, 0, 8, 'The Fall of Magtheridon', 'Magtheridon is dead, and with him falls the source of the fel orc army that Illidan Stormrage raised in Hellfire Citadel. The manufactory beneath the fortress has stopped its grim work, at least for now. Of the pit lord there remain a few trinkets and his severed head, a trophy fit for a hero of the Alliance or the Horde, and it belongs with the commanders who have fought the fel orcs since the portal opened: Force Commander Danath Trollbane at Honor Hold, or Nazgrel at Thrallmar.', 'quests 11002 (to Danath, Alliance) and 11003 (to Nazgrel, Horde) descriptions, completion and reward text; item 32385/32386 Magtheridon''s Head, dropped by Magtheridon 17257, starts 11002/11003; hellfire.json 348305 notes (11002/11003 left for a Hellfire Citadel file)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(383601, 1, 0, 255, 'When his jailers were attacked, his bonds began to weaken, and at last he tore free, roaring that he was unleashed. He fought in a fury that shook the floor beneath them, and when pressed hard he called on the walls of his prison to tremble and fall, and the roof came down around the fighters. He died with a final threat: the Legion would consume them all.', 'creature_text 17257 groups 1 (I... am... unleashed!), 4 (Let the walls of this prison tremble... and fall!), 5 (The Legion will consume you all!), 6 and 8 (bonds weaken; breaks free); boss_magtheridon.cpp (bonds weaken on engage; release after two minutes or when the last channeler dies; Quake; at 30 percent the hall and columns collapse)'),
(383602, 1, 0, 255, 'The commander took the head and spoke of what it meant. The blow fell on Illidan and on the Legion both, for a pit lord commander had been defeated, and the Legion''s siege of Hellfire Citadel no longer served any purpose; its efforts would surely turn to the Black Temple. Redemption was coming for Illidan, the commander said, and soon. For the first time in as long as the commander could remember, there was silence.', 'quests 11002 and 11003 reward text (identical: not only a blow to Illidan; a pit lord commander has been defeated; the siege of Hellfire Citadel now holds no purpose for the Burning Legion; efforts turned upon the Black Temple; Redemption comes for Illidan... and soon) and completion text (For the first time - in as long as I can remember - there is silence)');
